A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:WARRIOR:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A shield is useful. A {item} belongs in the plan as well.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:WARRIOR:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I would rather spend a stone than make the healer chase me.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:WARRIOR:voice-03]==],category="healthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[That is one emergency dealt with. Keep the line steady.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:WARRIOR:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My last {item} is gone. I will need a sound shield and a quieter fight.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:WARRIOR:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[No stones left on my belt. I cannot repeat that escape.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:WARRIOR:voice-01]==],category="potion",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A potion now costs less than replacing the armour later.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:WARRIOR:voice-02]==],category="potion",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I can hold a line. I am not too proud to open a bottle.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:WARRIOR:voice-03]==],category="potion",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Give me one breath and this {item}; then we can advance.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:WARRIOR:voice-01]==],category="potion",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My potion belt is empty. The next plan needs fewer heroic assumptions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:WARRIOR:voice-02]==],category="potion",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[That was my last {item}. Let us make the shield do its proper work.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:WARRIOR:voice-01]==],category="drink",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[There is time to check a blade while I finish this drink.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:WARRIOR:voice-02]==],category="drink",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Even the best-drilled company stops for water.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:WARRIOR:voice-03]==],category="drink",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I have swallowed enough battlefield dust for one day.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:WARRIOR:voice-01]==],category="drink",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My waterskin is empty. A forced march will not refill it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:WARRIOR:voice-02]==],category="drink",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Last of my {item}. Mark a water stop before we move again.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:WARRIOR:voice-01]==],category="food",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[We can discuss tactics over {item}. I think better with a meal.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:WARRIOR:voice-02]==],category="food",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A good ration keeps a soldier marching longer than a fine speech.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:WARRIOR:voice-03]==],category="food",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Let me eat before somebody mistakes hunger for a battle cry.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:WARRIOR:voice-01]==],category="food",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Last ration. I would welcome an enemy with a well-stocked kitchen.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:WARRIOR:voice-02]==],category="food",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[No {item} left. Put provisions beside ammunition on the supply list.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:WARRIOR:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I would rather prepare a meal than improvise an excuse for losing.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:WARRIOR:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Check the straps while I finish. The food is part of getting ready.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:WARRIOR:voice-03]==],category="bufffood",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A well-fed company is a better prospect than a hungry charge.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:WARRIOR:voice-01]==],category="bufffood",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My prepared meals are gone. We need a cook before the next campaign.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:WARRIOR:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[That was the last {item}. Do not mistake an empty mess kit for readiness.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:WARRIOR:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[An elixir does not replace training. I am happy to bring both.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:WARRIOR:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[The quartermaster charged enough for this to deserve a careful dose.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:WARRIOR:voice-03]==],category="elixir",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A little {item} before we put our equipment to the test.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:WARRIOR:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My last elixir is gone. I will be relying on practice next time.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:WARRIOR:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[No more {item}. The armoury has better stock than my alchemy pouch.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:WARRIOR:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Watch the approach while I bind this. I am keeping the shield close.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:WARRIOR:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A little cloth now should keep the blood inside the armour.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:WARRIOR:voice-03]==],category="bandage",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Hold the line a moment. There is no honour in neglecting a wound.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:WARRIOR:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My last bandage is used. The medical supplies need attention.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:WARRIOR:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[No {item} left. Let us avoid testing how much the armour can absorb.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:WARRIOR:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[To the people who stand beside us when the line gets thin.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:WARRIOR:voice-02]==],category="alcohol",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[One drink to our company, not an invitation to start another campaign.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:WARRIOR:voice-03]==],category="alcohol",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I have heard better battle plans after worse ale. That is not advice.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:WARRIOR:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My final {item} is gone. The mess tent owes me a visit.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:WARRIOR:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[No drinks left in my pack. I will toast the next victory with words.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:WARRIOR:voice-01]==],category="other",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[Useful supplies deserve a place beside useful steel.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:WARRIOR:voice-02]==],category="other",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A warrior can appreciate a tool that has no edge.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:WARRIOR:voice-03]==],category="other",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I have carried this {item} through enough marches. Let us use it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:WARRIOR:voice-01]==],category="other",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My last {item} is gone. The quartermaster will hear about the shortage.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:WARRIOR:voice-02]==],category="other",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[The supply pouch is empty. We shall need another answer next time.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:WARRIOR:voice-01]==],category="hearthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I am heading back to the hearth. Keep your shields high.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:WARRIOR:voice-02]==],category="hearthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[The march home begins here. Thank you for holding the line with me.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:WARRIOR:voice-03]==],category="hearthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I am taking my leave before someone finds another battle to volunteer us for.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:PALADIN:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[The Light asks for resolve, not for neglecting the supplies.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:PALADIN:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I can accept a strange remedy without surrendering my judgement.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:PALADIN:voice-03]==],category="healthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[This {item} is a precaution, not a replacement for our care.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:PALADIN:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My last {item} is gone. Please keep the next approach measured.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:PALADIN:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No stones left in my pack. Faith will not put another there.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:PALADIN:voice-01]==],category="potion",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A prayer and a potion need not be rivals.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:PALADIN:voice-02]==],category="potion",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I keep {item} within reach because preparation is a duty too.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:PALADIN:voice-03]==],category="potion",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[One draught, then I will be ready to stand beside you.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:PALADIN:voice-01]==],category="potion",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My potion reserve is empty. Let us not confuse courage with spare bottles.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:PALADIN:voice-02]==],category="potion",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[That was my last {item}. We should replenish our remedies before pressing on.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:PALADIN:voice-01]==],category="drink",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Even an earnest vigil needs a pause for water.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:PALADIN:voice-02]==],category="drink",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Let me drink. The next watch deserves a clear head.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:PALADIN:voice-03]==],category="drink",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I brought {item} for the road; sermons are a poor substitute.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:PALADIN:voice-01]==],category="drink",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My waterskin is empty. The next stop needs a clean well.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:PALADIN:voice-02]==],category="drink",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No {item} left. I would like to keep the next vigil somewhere near water.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PALADIN:voice-01]==],category="food",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A shared meal is a worthy use of a peaceful moment.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PALADIN:voice-02]==],category="food",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Let me finish the {item}. The road will still need our attention.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PALADIN:voice-03]==],category="food",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[There is no virtue in wasting good provisions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:PALADIN:voice-01]==],category="food",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My last ration is gone. We should make room for a provisioner.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:PALADIN:voice-02]==],category="food",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No {item} remains. I cannot feed a travelling party with good intentions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:PALADIN:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A careful meal is one more way to honour the people relying on us.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:PALADIN:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I intend to begin this task prepared, not merely persuaded.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:PALADIN:voice-03]==],category="bufffood",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Give the cook a little patience. Our armour has received enough already.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:PALADIN:voice-01]==],category="bufffood",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My prepared food is gone. We need to attend to that before another expedition.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:PALADIN:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[That was the final {item}. Good intentions have left an empty plate.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:PALADIN:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I have checked the seal. We owe our companions careful preparations.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:PALADIN:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A measured dose is easier to defend than a reckless one.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:PALADIN:voice-03]==],category="elixir",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Let me see to this {item} before we set out.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:PALADIN:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My last elixir is gone. I shall have to visit the alchemist after the chapel.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:PALADIN:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No {item} left. We should not build our plans around another dose.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:PALADIN:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Allow me a moment to bind this. Care belongs to the patient as well.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:PALADIN:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I will tend the wound before I offer advice about endurance.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:PALADIN:voice-03]==],category="bandage",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Keep watch, please. This {item} calls for both hands.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:PALADIN:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My last bandage is used. The next injured traveller will need other help.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:PALADIN:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No {item} left. I need to replenish the medical pouch.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:PALADIN:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[To safe roads, honest company, and a hearth for those still travelling.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:PALADIN:voice-02]==],category="alcohol",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[One toast to the people who brought us this far.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:PALADIN:voice-03]==],category="alcohol",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I would rather share a modest drink than make a grand promise over it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:PALADIN:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[The last {item} is gone. Let the company be enough for the next toast.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:PALADIN:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No drinks remain in my pack. Perhaps a quiet evening is in order.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:PALADIN:voice-01]==],category="other",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A humble tool can serve a worthy purpose.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:PALADIN:voice-02]==],category="other",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Let me attend to this {item}; duty includes the small preparations.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:PALADIN:voice-03]==],category="other",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I prefer a practical precaution to an avoidable apology.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:PALADIN:voice-01]==],category="other",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My final {item} is gone. I need to restore the supplies I rely upon.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:PALADIN:voice-02]==],category="other",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[No spare {item}. We must choose our next undertaking with care.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:PALADIN:voice-01]==],category="hearthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I am preparing to return to the hearth. May the Light keep your road.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:PALADIN:voice-02]==],category="hearthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[My watch here is ending. Thank you for sharing it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:PALADIN:voice-03]==],category="hearthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I am taking my leave. May we meet again under kinder circumstances.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:HUNTER:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I keep a {item} where I can reach it without dropping the trail.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:HUNTER:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Even a careful hunter benefits from an emergency supply.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:HUNTER:voice-03]==],category="healthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Give me a breath. I would rather not become something else's quarry.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:HUNTER:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last {item} is gone. We should choose our next trail carefully.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:HUNTER:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No stones left. I have traps and patience, but no spare of this.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:HUNTER:voice-01]==],category="potion",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I packed a potion beside the spare fletching for good reason.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:HUNTER:voice-02]==],category="potion",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A clean escape and a {item} are both useful to have.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:HUNTER:voice-03]==],category="potion",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Let me deal with this before I return to watching the trail.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:HUNTER:voice-01]==],category="potion",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last potion is gone. I would prefer to keep the next fight at a distance.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:HUNTER:voice-02]==],category="potion",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No {item} left. We need an alchemist as well as an ammunition stop.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:HUNTER:voice-01]==],category="drink",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A fresh drink makes a long tracking job more pleasant.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:HUNTER:voice-02]==],category="drink",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I can read the tracks while we stop for {item}.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:HUNTER:voice-03]==],category="drink",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Let the wildlife have the muddy puddles. I brought my own drink.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:HUNTER:voice-01]==],category="drink",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My water supply is gone. I will watch the trail for a spring.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:HUNTER:voice-02]==],category="drink",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[Last of my {item}. Let us refill before we lose the stream.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:HUNTER:voice-01]==],category="food",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I know where my next meal comes from. I am eating this one first.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:HUNTER:voice-02]==],category="food",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A good trail ration is worth its weight in the pack.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:HUNTER:voice-03]==],category="food",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Keep an eye on the treeline while I finish my {item}.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:HUNTER:voice-01]==],category="food",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last ration is gone. The next hunt may need to provide supper.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:HUNTER:voice-02]==],category="food",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No {item} left. We should find a provisioner before the tracks lead farther out.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:HUNTER:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Preparation begins before we pick up the trail.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:HUNTER:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Let me finish this meal before I take the forward watch.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:HUNTER:voice-03]==],category="bufffood",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I would rather eat properly here than hurry a mouthful through the brush.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:HUNTER:voice-01]==],category="bufffood",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[That was my final prepared meal. I need to stock up before another hunt.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:HUNTER:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No more {item}. I cannot pack an empty wrapper for the next expedition.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:HUNTER:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I check a bottle as carefully as I check a snare.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:HUNTER:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A measured dose of {item}, then we can take the trail again.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:HUNTER:voice-03]==],category="elixir",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[No reason to hurry the preparation when the quarry has already waited this long.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:HUNTER:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last elixir is used. I will need another before the next long pursuit.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:HUNTER:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No {item} left. We should mark an alchemist on the route back.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:HUNTER:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Please watch the treeline. I need a moment with this bandage.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:HUNTER:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I have patched enough cuts in the brush to value clean cloth.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:HUNTER:voice-03]==],category="bandage",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Let me finish this {item} before we follow anything into thorns.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:HUNTER:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last bandage is used. The next path ought to have fewer brambles.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:HUNTER:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No {item} left. I should replace the medical roll before we leave the road.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:HUNTER:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[To a dry camp and tracks that do not end at something hungry.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:HUNTER:voice-02]==],category="alcohol",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I will drink to a good day's tracking and a quiet night afterward.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:HUNTER:voice-03]==],category="alcohol",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A little {item} by the campfire sounds better than another muddy mile.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:HUNTER:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[That was my last {item}. The next campfire will have to provide its own cheer.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:HUNTER:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No drinks left. I will keep an eye out for an inn on the trail home.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:HUNTER:voice-01]==],category="other",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I like equipment that earns its place in the pack.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:HUNTER:voice-02]==],category="other",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A practical use for {item}; that is why I kept it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:HUNTER:voice-03]==],category="other",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Give me a moment to arrange the supplies before we follow on.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:HUNTER:voice-01]==],category="other",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last {item} is gone. I need to make room for a replacement.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:HUNTER:voice-02]==],category="other",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[No spare {item}. Let us not plan another crossing on the strength of it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:HUNTER:voice-01]==],category="hearthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I am heading back to the hearth. May your trail stay clear.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:HUNTER:voice-02]==],category="hearthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[My route home begins with this stone. Thank you for the company.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:HUNTER:voice-03]==],category="hearthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I am taking my leave. Keep a watch on the treeline for me.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:ROGUE:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I prefer an exit plan. This {item} is the smaller backup plan.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:ROGUE:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Give me a moment. I would rather leave on my own feet.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:ROGUE:voice-03]==],category="healthstone",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[An emergency supply is easier to carry than an elaborate explanation.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:ROGUE:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My last {item} is gone. I will be favouring the quieter exits.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:ROGUE:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[No stones left. Please do not include another miraculous escape in the plan.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:ROGUE:voice-01]==],category="potion",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I paid for the potion. I would rather not pay for the consequences of ignoring it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:ROGUE:voice-02]==],category="potion",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A discreet dose before this becomes an indiscreet problem.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:ROGUE:voice-03]==],category="potion",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Let me use the {item}. You may continue pretending not to notice.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:ROGUE:voice-01]==],category="potion",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My last potion is gone. Subtlety will have to earn its keep.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:ROGUE:voice-02]==],category="potion",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[No {item} left. I need an alchemist who does not ask many questions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:ROGUE:voice-01]==],category="drink",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A quiet drink. Some of us appreciate an uneventful moment.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:ROGUE:voice-02]==],category="drink",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I can watch the doorway while I finish my {item}.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:ROGUE:voice-03]==],category="drink",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A dry throat is an unnecessary distraction in my line of work.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:ROGUE:voice-01]==],category="drink",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My drink supply is gone. Even a discreet route should pass a well.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:ROGUE:voice-02]==],category="drink",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[Last of my {item}. We need water before another lengthy conversation in the shadows.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:ROGUE:voice-01]==],category="food",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[One mouthful before we discuss whose pockets need inspecting.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:ROGUE:voice-02]==],category="food",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Good food is worth acquiring honestly on occasion.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:ROGUE:voice-03]==],category="food",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Let me eat the {item}. It is the least suspicious thing in my pack.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:ROGUE:voice-01]==],category="food",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My last ration is gone. Someone should point me toward a kitchen.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:ROGUE:voice-02]==],category="food",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[No {item} left. I would rather find a merchant than improvise dinner.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:ROGUE:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A proper meal now should spare us an ill-timed growling stomach.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:ROGUE:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I am preparing carefully. You would miss me if I did not.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:ROGUE:voice-03]==],category="bufffood",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Give me time to finish the {item}; haste is how small mistakes become visible.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:ROGUE:voice-01]==],category="bufffood",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My prepared meals are gone. I need a provisioner before another discreet outing.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:ROGUE:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[No more {item}. I have checked the hidden pocket as well.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:ROGUE:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I read this label twice. Professional caution.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:ROGUE:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[An elixir is useful when its purpose is less mysterious than its seller.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:ROGUE:voice-03]==],category="elixir",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A measured dose before we try the difficult door.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:ROGUE:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My last elixir is gone. The remaining advantages will have to be personal.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:ROGUE:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[No {item} left. I cannot produce another from a concealed sleeve.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:ROGUE:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Keep an eye on the entrance while I use this {item}.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:ROGUE:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A little clean cloth. We need not tell a colourful story about the cut.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:ROGUE:voice-03]==],category="bandage",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I would prefer to stop leaving evidence on the floor.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:ROGUE:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My last bandage is used. We should make the next approach less personal.]==]}
