A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:ROGUE:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A toast to closed mouths and conveniently open doors.]==]}
