A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PRIEST:voice-01]==],category="food",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[A shared meal is a good beginning for any conversation.]==]}
