A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:last:say:Scourge:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[That was the final {item}. I do not intend to replace dinner with nostalgia.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:regular:say:Scourge:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[I can admire an apothecary's precision while questioning the aftertaste.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:regular:say:Scourge:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[The label on this {item} is more reassuring than the smell.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Scourge:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[My last elixir is gone. I shall add it to the apothecary's growing list.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Scourge:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[No {item} left. An empty bottle has very limited medicinal ambitions.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:regular:say:Scourge:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[Clean cloth is a small courtesy to whatever still holds together.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:regular:say:Scourge:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[Keep watch while I use the {item}. I would rather retain all the pieces.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Scourge:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[My last bandage is used. Loose ends are not a figure of speech for everyone.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Scourge:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[No {item} remains. I should find clean wrapping before another part complains.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:regular:say:Scourge:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[A toast to the company we choose, rather than the graves assigned to us.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:regular:say:Scourge:voice-02]==],category="alcohol",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[I remember better vintages. I also remember worse evenings than this.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Scourge:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[That was my last {item}. Even the dead can misjudge the evening's provisions.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Scourge:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[No drinks left. We shall have to sustain the conversation by less bottled means.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Scourge:voice-01]==],category="other",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[A practical use for {item}. I have a particular fondness for things that keep working.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Scourge:voice-02]==],category="other",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[We should make the best of what remains. I have had practice.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Scourge:voice-01]==],category="other",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[My last {item} is gone. Another empty pocket in a rather long career of them.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Scourge:voice-02]==],category="other",language="en",stock=true,channel="say",source="Scourge",migrationMatch=false,text=[==[No spare {item}. Please do not suggest digging up another without a very good reason.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[hearthstone:en:regular:say:Scourge:voice-01]==],category="hearthstone",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[I am returning to the hearth. A room with fewer drafts sounds remarkably attractive.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[hearthstone:en:regular:say:Scourge:voice-02]==],category="hearthstone",language="en",stock=false,channel="say",source="Scourge",migrationMatch=false,text=[==[I am taking my leave. Thank you for treating the company as something more than a curiosity.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:regular:say:Human:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A {item} is a better precaution than a stirring account of my bravery.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:regular:say:Human:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I have heard enough tavern stories about people who saved their supplies for too late.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:last:say:Human:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last {item} is gone. The next town needs to feature in our plans.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:last:say:Human:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No stones remain. We should arrange another before this becomes a story told in past tense.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:regular:say:Human:voice-01]==],category="potion",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A potion now, then we can carry on with something resembling good judgement.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:regular:say:Human:voice-02]==],category="potion",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[Somewhere there is an alchemist who thinks the taste of {item} is acceptable.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:last:say:Human:voice-01]==],category="potion",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last potion is gone. We should make the next market stop a useful one.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:last:say:Human:voice-02]==],category="potion",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No {item} left. I would rather explain the expense than the empty belt.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:regular:say:Human:voice-01]==],category="drink",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A drink before we debate the route again. I have learned that lesson on enough roads.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:regular:say:Human:voice-02]==],category="drink",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[There are worse comforts than {item} and companions who know when to pause.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:last:say:Human:voice-01]==],category="drink",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My drink supply has run dry. I shall be watching for a village well.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:last:say:Human:voice-02]==],category="drink",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[Last of my {item}. The next inn sign will have my full attention.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:regular:say:Human:voice-01]==],category="food",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A shared meal does more for a travelling party than another argument about directions.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:regular:say:Human:voice-02]==],category="food",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[This {item} reminds me why people build kitchens instead of living on the road.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:last:say:Human:voice-01]==],category="food",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last ration is gone. I would like the next village to have a baker.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:last:say:Human:voice-02]==],category="food",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No {item} left. That is a shortcoming of my packing, not an invitation to skip supper.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:regular:say:Human:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[Somebody put care into this meal. I intend to show the same courtesy in eating it.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:regular:say:Human:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[Give me a moment for {item}; even grand undertakings begin with ordinary provisions.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:last:say:Human:voice-01]==],category="bufffood",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My prepared meals are gone. We need another visit to a proper cook.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:last:say:Human:voice-02]==],category="bufffood",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[That was the final {item}. I have made a very ordinary note about buying more.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:regular:say:Human:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A measured dose and a legible label. Small mercies on a difficult road.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:regular:say:Human:voice-02]==],category="elixir",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I paid a fair price for this {item}. I hope the alchemist shares my definition of fair.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Human:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last elixir is used. Another market visit is becoming hard to postpone.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Human:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No {item} remains. We shall need to plan with fewer bottles and better information.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:regular:say:Human:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[Keep watch while I finish this wrapping. Nobody wins an argument with a neglected wound.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:regular:say:Human:voice-02]==],category="bandage",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I packed the {item} before the spare shirt. A rare sound decision.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Human:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last bandage is used. We should find a medical supplier in the next town.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Human:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No {item} left. The road has been less kind to my supplies than I expected.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:regular:say:Human:voice-01]==],category="alcohol",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[To a full table, a sound roof, and friends who tell the truth about the road.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:regular:say:Human:voice-02]==],category="alcohol",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I would drink to our reputation, but I suspect the innkeeper has heard another version.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Human:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[That was my last {item}. We shall need a tavern if the evening develops another toast.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Human:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No drinks remain. I hope the next innkeeper accepts a less dramatic account of our journey.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Human:voice-01]==],category="other",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I grew up hearing that useful things should earn the space they take. Here is {item}'s chance.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Human:voice-02]==],category="other",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[A little practical preparation before our ambitions get ahead of our belongings.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Human:voice-01]==],category="other",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[My last {item} is gone. There is another entry for the market list.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Human:voice-02]==],category="other",language="en",stock=true,channel="say",source="Human",migrationMatch=false,text=[==[No spare {item}. We should not leave the next town before fixing that.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[hearthstone:en:regular:say:Human:voice-01]==],category="hearthstone",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I am beginning the journey home. May your next road lead to a welcoming door.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[hearthstone:en:regular:say:Human:voice-02]==],category="hearthstone",language="en",stock=false,channel="say",source="Human",migrationMatch=false,text=[==[I am taking my leave. Thank you for a story worth telling somewhere comfortable.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:regular:say:Dwarf:voice-01]==],category="healthstone",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[A {item} and a stout grip. I can appreciate both kinds of preparation.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:regular:say:Dwarf:voice-02]==],category="healthstone",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[I prefer remedies that are less mysterious than a sealed tomb, but this will do.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:last:say:Dwarf:voice-01]==],category="healthstone",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My last {item} is gone. We need a supplier before the next deep passage.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[healthstone:en:last:say:Dwarf:voice-02]==],category="healthstone",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[No stones left. I would rather carry another than depend on the mercy of a tunnel.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:regular:say:Dwarf:voice-01]==],category="potion",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[This {item} has a sharp finish. I have had mountain air that was kinder.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:regular:say:Dwarf:voice-02]==],category="potion",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[A potion deserves a place beside the spare buckles and sound rope.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:last:say:Dwarf:voice-01]==],category="potion",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My last potion is used. Put an alchemist on the route back to the forge.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:last:say:Dwarf:voice-02]==],category="potion",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[No {item} remains. The bottle is no more useful empty than an unfired furnace.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:regular:say:Dwarf:voice-01]==],category="drink",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[A long climb teaches respect for a well-filled waterskin.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:regular:say:Dwarf:voice-02]==],category="drink",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[Let me drink the {item}. I have swallowed enough dust from this road.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:last:say:Dwarf:voice-01]==],category="drink",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My water supply is gone. We should find a spring before another climb.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[drink:en:last:say:Dwarf:voice-02]==],category="drink",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[Last of my {item}. A dry pack is a poor companion in the mountains.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:regular:say:Dwarf:voice-01]==],category="food",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[A meal tastes better with a roof overhead, but I will not insult the provisions.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:regular:say:Dwarf:voice-02]==],category="food",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[Give me a moment with {item}. A hungry traveller makes poor company in a narrow tunnel.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:last:say:Dwarf:voice-01]==],category="food",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My last ration is gone. I could do with an inn that takes its kitchen seriously.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:last:say:Dwarf:voice-02]==],category="food",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[No {item} left. The road had better lead somewhere with a decent hearth.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:regular:say:Dwarf:voice-01]==],category="bufffood",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[A careful meal is as sound a preparation as checking the rivets.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:regular:say:Dwarf:voice-02]==],category="bufffood",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[Whoever packed this {item} understands the value of an expedition's provisions.]==]}
