A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:regular:say:Dwarf:voice-01]==],category="elixir",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[I trust a measured elixir more than a seller promising the strength of a mountain.]==]}
