A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Dwarf:voice-01]==],category="elixir",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My last elixir is gone. I must restock before we attempt another hard climb.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[elixir:en:last:say:Dwarf:voice-02]==],category="elixir",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[No {item} left. I have empty glass where a useful draught ought to be.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:regular:say:Dwarf:voice-01]==],category="bandage",language="en",stock=false,channel="say",source="Dwarf",migrationMatch=false,text=[==[Watch the passage while I fasten this. Cloth belongs in a delver's pack as surely as a lamp.]==]}
