A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Dwarf:voice-01]==],category="bandage",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[My last bandage is used. We should replace the wrapping before the next descent.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Dwarf:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="Dwarf",migrationMatch=false,text=[==[No {item} remains. A visit to the medical supplier is no longer optional for me.]==]}
