A.RaceEntries[#A.RaceEntries+1]={id=[==[bandage:en:last:say:Troll:voice-02]==],category="bandage",language="en",stock=true,channel="say",source="Troll",migrationMatch=false,text=[==[No {item} remains. Let us avoid giving the medical pouch more work than it can hold.]==]}
