A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Troll:voice-01]==],category="alcohol",language="en",stock=true,channel="say",source="Troll",migrationMatch=false,text=[==[That was my last {item}. The next toast needs a more generous pack than mine.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Troll:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="Troll",migrationMatch=false,text=[==[No drinks remain. We can leave the next round to a welcoming inn.]==]}
