A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Troll:voice-01]==],category="other",language="en",stock=true,channel="say",source="Troll",migrationMatch=false,text=[==[My last {item} is gone. We should trade for another before travelling farther.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:last:say:Troll:voice-02]==],category="other",language="en",stock=true,channel="say",source="Troll",migrationMatch=false,text=[==[No spare {item}. Please do not place that part of the plan in my empty pocket.]==]}
