A.RaceEntries[#A.RaceEntries+1]={id=[==[potion:en:regular:say:Skyborne:voice-01]==],category="potion",language="en",stock=false,channel="say",source="Skyborne",migrationMatch=false,text=[==[A potion before the road asks for more than a steady stride.]==]}
