A.RaceEntries[#A.RaceEntries+1]={id=[==[alcohol:en:last:say:Skyborne:voice-02]==],category="alcohol",language="en",stock=true,channel="say",source="Skyborne",migrationMatch=false,text=[==[No drinks remain. The wind can carry a song, but it will not refill this bottle.]==]}
