A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Skyborne:voice-02]==],category="other",language="en",stock=false,channel="say",source="Skyborne",migrationMatch=false,text=[==[I brought {item} because an open sky is no excuse for an unprepared pack.]==]}
