A.RaceEntries[#A.RaceEntries+1]={id=[==[food:en:regular:say:Skyborne:voice-03]==],category="food",language="en",stock=false,channel="say",source="Skyborne",migrationMatch=false,text=[==[A meal and an open view make a good pause between unfamiliar horizons.]==]}
A.RaceEntries[#A.RaceEntries+1]={id=[==[bufffood:en:regular:say:Skyborne:voice-03]==],category="bufffood",language="en",stock=false,channel="say",source="Skyborne",migrationMatch=false,text=[==[I packed this {item} for demanding journeys, not merely for the pleasure of carrying it.]==]}
