A.RaceEntries[#A.RaceEntries+1]={id=[==[other:en:regular:say:Skyborne:voice-03]==],category="other",language="en",stock=false,channel="say",source="Skyborne",migrationMatch=false,text=[==[A small use for {item} before we follow the next change in the weather.]==]}
