A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:WARRIOR:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[One {item}. I would rather use the emergency stores than leave them to the next soldier.]==]}
