A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:WARRIOR:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My wrapping is gone. I need fresh bandages before another rough passage.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:WARRIOR:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A modest drink to the companions who come back for the last person in the line.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:WARRIOR:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[My contribution to the drinks is finished. The next round will have to wait for the mess hall.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:WARRIOR:voice-04]==],category="other",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[A sensible use for this {item}; there is more to preparation than a sharpened edge.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:WARRIOR:voice-03]==],category="other",language="en",stock=true,channel="say",source="WARRIOR",migrationMatch=false,text=[==[That is the last of this supply. We should amend the inventory before the next march.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:WARRIOR:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="WARRIOR",migrationMatch=false,text=[==[I am returning to the hearth. May the next watch be quieter than the last.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:PALADIN:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I will accept the precaution and remain responsible for the choice.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:PALADIN:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My final stone is spent. The next preparation needs more than a solemn promise.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:PALADIN:voice-04]==],category="potion",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I packed the potion because care begins before anybody needs a rescue.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:PALADIN:voice-03]==],category="potion",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My last potion is used. I will not make a promise on behalf of an empty bottle.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:PALADIN:voice-04]==],category="drink",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Let us take a peaceful moment for water while we have one.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:PALADIN:voice-03]==],category="drink",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[I have no drink left for the next watch. A refill belongs among our duties.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PALADIN:voice-04]==],category="food",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[We can share the news after I have shared a little time with my meal.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:PALADIN:voice-03]==],category="food",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My provisions are finished. We should not neglect the ordinary work of feeding the company.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:PALADIN:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[A good cook has done a part of the work before we lift a shield.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:PALADIN:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[I have no prepared food for another outing. We owe our next companions better preparation.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:PALADIN:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[One careful dose of {item}. Resolve and attention should travel together.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:PALADIN:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My elixir store is finished. The next expedition needs a properly replenished pouch.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:PALADIN:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Patience, please. A wound deserves more care than a hurried knot.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:PALADIN:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My clean wrapping is gone. I must restore the medical kit before tending another road.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:PALADIN:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[To those who kept a place at the table for the late arrivals.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:PALADIN:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[My part of the drinks is finished. We can still offer one another a generous evening.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:PALADIN:voice-04]==],category="other",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[Useful preparations are often quieter than the duties they make possible.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:PALADIN:voice-03]==],category="other",language="en",stock=true,channel="say",source="PALADIN",migrationMatch=false,text=[==[That is the final one from my stores. I would rather report the shortage than conceal it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:PALADIN:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="PALADIN",migrationMatch=false,text=[==[I am beginning the journey back. May your next watch end with everyone accounted for.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:HUNTER:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I value an emergency supply that stays quiet until I need it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:HUNTER:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My final stone is used. I will keep a little more space between myself and our next problem.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:HUNTER:voice-04]==],category="potion",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Let me finish the potion. The trail will not disappear while I swallow.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:HUNTER:voice-03]==],category="potion",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My potion supply is finished. I must replace it before another demanding pursuit.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:HUNTER:voice-04]==],category="drink",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A well-filled waterskin is a better companion than a confidently drawn route.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:HUNTER:voice-03]==],category="drink",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[I have no drink left. We should check the low ground for a sensible refill stop.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:HUNTER:voice-04]==],category="food",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I packed food as carefully as the rest of the gear. Let us make use of it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:HUNTER:voice-03]==],category="food",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My provisions are finished. I should have given the next meal more room in the pack.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:HUNTER:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A meal here should keep the next stretch of tracking from becoming an argument.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:HUNTER:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[I have no prepared food left. The next hunt requires a visit to a cook first.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:HUNTER:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I checked the bottle before leaving the road. Let me finish what I prepared.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:HUNTER:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My elixir supply is finished. We should arrange another before setting out at dawn.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:HUNTER:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[Watch the brush while I finish. I would prefer not to interrupt the wrapping twice.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:HUNTER:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My last clean wrapping is gone. We need to put a medical supplier on the return route.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:HUNTER:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[To trails that lead somewhere worth the walk and camps that stay dry.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:HUNTER:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[My part of the drinks is finished. A quiet campfire can carry the rest of the evening.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:HUNTER:voice-04]==],category="other",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[A useful piece of gear should get a chance to earn the space it occupies.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:HUNTER:voice-03]==],category="other",language="en",stock=true,channel="say",source="HUNTER",migrationMatch=false,text=[==[That is the final one in my gear. I need to replace it before depending on that route again.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:HUNTER:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="HUNTER",migrationMatch=false,text=[==[I am returning to the hearth. May every track you choose lead to a safe return.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:ROGUE:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A discreet emergency supply. I approve of that combination.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:ROGUE:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My final stone is used. I will need a rather more ordinary exit next time.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:ROGUE:voice-04]==],category="potion",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[One swallow, then we can return to the part of the plan with fewer witnesses.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:ROGUE:voice-03]==],category="potion",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My potion supply is finished. I am no longer equipped for that particular surprise.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:ROGUE:voice-04]==],category="drink",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A drink before we return to whispering about the route.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:ROGUE:voice-03]==],category="drink",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[I have no drink left. Even a concealed flask must be refilled occasionally.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:ROGUE:voice-04]==],category="food",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[Let me finish eating before you ask me to move quietly again.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:ROGUE:voice-03]==],category="food",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My provisions are finished. Finding a kitchen is suddenly an excellent use of discretion.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:ROGUE:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[A proper meal should spare us a stomach announcing our approach.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:ROGUE:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[I have no prepared food left. We should settle that before the next silent departure.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:ROGUE:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I would rather measure this dose than develop an interesting explanation for it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:ROGUE:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My elixir supply is finished. I need a replacement that comes with a trustworthy stopper.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:ROGUE:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[This wrapping needs a moment. The cut is already conspicuous enough.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:ROGUE:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My clean bandaging is finished. I would prefer the next encounter to leave fewer marks.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:ROGUE:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[To our good fortune and the people who know when not to describe it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:ROGUE:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[My part of the drinks is finished. Nobody should expect another bottle from my sleeve.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:ROGUE:voice-04]==],category="other",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I enjoy having the right small thing before the wrong large thing happens.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:ROGUE:voice-03]==],category="other",language="en",stock=true,channel="say",source="ROGUE",migrationMatch=false,text=[==[That is the final one I kept aside. We should revise the contingency while it is still a plan.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:ROGUE:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="ROGUE",migrationMatch=false,text=[==[I am beginning the journey back. Please tell the innkeeper the least complicated version.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:PRIEST:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[A moment for the remedy before I return to worrying about the company.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:PRIEST:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My final stone is used. I need to restore that part of the care I can offer myself.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:PRIEST:voice-04]==],category="potion",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[I can appreciate a simple medicine without requiring it to answer every problem.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:PRIEST:voice-03]==],category="potion",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My potion supply is finished. We should consider that before asking more of the next watch.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:PRIEST:voice-04]==],category="drink",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[A quiet cup gives everyone a chance to lower their voice.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:PRIEST:voice-03]==],category="drink",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[I have no drink left. I would appreciate a refill before the next long vigil.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:PRIEST:voice-04]==],category="food",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[Let us give the meal as much attention as the discussion of our troubles.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:PRIEST:voice-03]==],category="food",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My provisions are finished. I should remember to include myself in the next shopping list.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:PRIEST:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[A good meal is a kind beginning for a difficult undertaking.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:PRIEST:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[I have no prepared food left. The next company deserves a better stocked healer.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:PRIEST:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[Please allow me a moment to attend to this measured draught.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:PRIEST:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My elixir supply is finished. I need to renew those preparations before another long task.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:PRIEST:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[One careful knot. Then we can discuss what needs tending next.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:PRIEST:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My medical cloth is finished. I will need more before another journey with injuries to tend.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:PRIEST:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[To a company that notices when the quietest person needs a place to rest.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:PRIEST:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[My part of the drinks is finished. I can still offer an attentive ear for the evening.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:PRIEST:voice-04]==],category="other",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[Care sometimes looks like remembering to pack an ordinary useful object.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:PRIEST:voice-03]==],category="other",language="en",stock=true,channel="say",source="PRIEST",migrationMatch=false,text=[==[That is the final one from my supplies. We should find a replacement while we have shelter.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:PRIEST:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="PRIEST",migrationMatch=false,text=[==[I am returning to the hearth. May those still on the road find rest when they need it.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:SHAMAN:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[A practical precaution is worth keeping close on an uncertain journey.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:SHAMAN:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My final stone is used. Let us account for the empty place before going farther.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:SHAMAN:voice-04]==],category="potion",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[Let me finish the potion. There is wisdom in attending to the step we are taking.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:SHAMAN:voice-03]==],category="potion",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My potion supply is finished. The next journey needs time for ordinary restocking.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:SHAMAN:voice-04]==],category="drink",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[A pause for water gives us time to hear what haste has drowned out.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:SHAMAN:voice-03]==],category="drink",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[I have no drink left. Let us choose a water stop with the same care as the route itself.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:SHAMAN:voice-04]==],category="food",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[I would rather taste the meal than hurry past another useful kindness.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:SHAMAN:voice-03]==],category="food",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My provisions are finished. We should restore what the journey has taken from the pack.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:SHAMAN:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[A meal taken with patience can be part of a steadier beginning.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:SHAMAN:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[I have no prepared food left. The next task should wait for sound provisions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:SHAMAN:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[One careful draught before we put our attention back on the road.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:SHAMAN:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My elixir supply is finished. I need to renew the preparation rather than assume it remains.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:SHAMAN:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[Please watch the passage. This wound calls for an unhurried hand.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:SHAMAN:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My clean wrapping is finished. We should find fresh supplies before seeking another hard path.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:SHAMAN:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[To companions who leave room for one another beside the fire.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:SHAMAN:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[My part of the drinks is finished. The company can still make the evening a warm one.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:SHAMAN:voice-04]==],category="other",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[There is room for a practical tool among the things we learn to trust.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:SHAMAN:voice-03]==],category="other",language="en",stock=true,channel="say",source="SHAMAN",migrationMatch=false,text=[==[That is the final one in my stores. We should replace it before the next departure.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:SHAMAN:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="SHAMAN",migrationMatch=false,text=[==[I am beginning the journey back. May a kind fire meet you when your own road ends.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:MAGE:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[A compact remedy is a useful answer to a very immediate problem.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:last:say:MAGE:voice-03]==],category="healthstone",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My final stone is used. Please remove that particular contingency from the calculation.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:regular:say:MAGE:voice-04]==],category="potion",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[One measured swallow. A busy mind is no excuse for neglecting the bottle.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:MAGE:voice-03]==],category="potion",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My potion supply is finished. I need an alchemist to correct that part of the inventory.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:MAGE:voice-04]==],category="drink",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[I can review the route while we make a perfectly ordinary stop for water.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:last:say:MAGE:voice-03]==],category="drink",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[I have no drink left. A lengthy explanation will not improve the state of the flask.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:regular:say:MAGE:voice-04]==],category="food",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[Let me finish the meal before I return to the less digestible questions.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[food:en:last:say:MAGE:voice-03]==],category="food",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My provisions are finished. I have enough reading for the road, but no supper.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:MAGE:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[The cook has done useful work. I intend to give it the time it deserves.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:last:say:MAGE:voice-03]==],category="bufffood",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[I have no prepared food left. The next expedition needs a more practical supply calculation.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:MAGE:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[I will give the dose my full attention before attempting anything less straightforward.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:MAGE:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My elixir supply is finished. An empty vial is not the same preparation in a lighter form.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:MAGE:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[A little patience with this bandage should prevent a much less convenient interruption.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:MAGE:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My clean wrapping is finished. I must buy medical cloth as well as the more interesting supplies.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:MAGE:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[To knowledge acquired without an unfortunate demonstration of its limits.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:MAGE:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[My part of the drinks is finished. I cannot responsibly count the empty bottle as another serving.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:regular:say:MAGE:voice-04]==],category="other",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[A useful object with a clear purpose. I occasionally appreciate the absence of mystery.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[other:en:last:say:MAGE:voice-03]==],category="other",language="en",stock=true,channel="say",source="MAGE",migrationMatch=false,text=[==[That is the final one in my equipment. We need a replacement rather than a better theory of one.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[hearthstone:en:regular:say:MAGE:voice-04]==],category="hearthstone",language="en",stock=false,channel="say",source="MAGE",migrationMatch=false,text=[==[I am returning to the hearth. May the next discussion you have be shorter than the journey.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[healthstone:en:regular:say:WARLOCK:voice-04]==],category="healthstone",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[A well-placed emergency supply is more useful than another warning about my methods.]==]}
