A.ClassEntries[#A.ClassEntries+1]={id=[==[potion:en:last:say:WARLOCK:voice-03]==],category="potion",language="en",stock=true,channel="say",source="WARLOCK",migrationMatch=false,text=[==[My potion supply is finished. The next sensible answer requires a visit to the alchemist.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[drink:en:regular:say:WARLOCK:voice-04]==],category="drink",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[A plain drink and a short pause. Neither needs an elaborate explanation.]==]}
