A.ClassEntries[#A.ClassEntries+1]={id=[==[bufffood:en:regular:say:WARLOCK:voice-04]==],category="bufffood",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[A proper meal is an agreeably uncomplicated investment in the next undertaking.]==]}
