A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:regular:say:WARLOCK:voice-04]==],category="elixir",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[One careful draught of {item}. I prefer my surprises to be intentional.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[elixir:en:last:say:WARLOCK:voice-03]==],category="elixir",language="en",stock=true,channel="say",source="WARLOCK",migrationMatch=false,text=[==[My elixir supply is finished. I cannot get another dose from an intimidating label.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:regular:say:WARLOCK:voice-04]==],category="bandage",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[Keep the approach clear. I would rather finish this wrapping without an audience.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[bandage:en:last:say:WARLOCK:voice-03]==],category="bandage",language="en",stock=true,channel="say",source="WARLOCK",migrationMatch=false,text=[==[My clean bandaging is finished. The next remedy needs a supplier with actual cloth.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:regular:say:WARLOCK:voice-04]==],category="alcohol",language="en",stock=false,channel="say",source="WARLOCK",migrationMatch=false,text=[==[To an uneventful conclusion and an innkeeper who believes in closing time.]==]}
A.ClassEntries[#A.ClassEntries+1]={id=[==[alcohol:en:last:say:WARLOCK:voice-03]==],category="alcohol",language="en",stock=true,channel="say",source="WARLOCK",migrationMatch=false,text=[==[My part of the drinks is finished. I will not improve the evening by promising an impossible refill.]==]}
